package main

const modelControlsHTML = `<div class="toolbar"><label>資料範圍<select id="model-scope"><option value="MY_KEYS">My Models · 我的 Key</option><option value="GLOBAL">Global Catalog</option></select></label><label>排序<select id="model-sort"><option value="smart">綜合排序</option><option value="name">名稱</option><option value="recent">最近使用</option><option value="new">最近加入</option><option value="strength">模型強度</option><option value="tps">TPS</option><option value="ttft">TTFT</option><option value="latency">延遲</option><option value="quota">額度</option><option value="price">輸入價格</option></select></label></div><label>效能來源<select id="model-performance-source"><option value="local">我的實測</option><option value="provider">Provider 回報</option><option value="external">External 參考</option></select></label><div class="toolbar"><label>Key<select id="model-key"><option value="">全部我的 Key</option></select></label><label>Group<select id="model-group"><option value="">全部 Group</option></select></label></div><div class="toolbar"><label>類別<select id="model-category"><option value="">全部</option><option>CHAT_REASONING</option><option>CODING</option><option>IMAGE</option><option>AUDIO</option><option>EMBEDDING</option><option>RERANK</option><option>SAFETY</option><option>OTHER</option></select></label><label>模態<select id="model-modality"><option value="">全部</option><option>TEXT_INPUT</option><option>TEXT_OUTPUT</option><option>IMAGE_INPUT</option><option>IMAGE_OUTPUT</option><option>AUDIO_INPUT</option><option>AUDIO_OUTPUT</option><option>FILE_INPUT</option></select></label></div><label>Vendor<input id="model-vendor" type="search"></label><div class="toolbar"><label>最低 Context<input id="model-context-min" type="number" min="0"></label><label>最低 TPS<input id="model-tps-min" type="number" min="0" step="any"></label><label>最高 TTFT（ms）<input id="model-ttft-max" type="number" min="0"></label><label>最高延遲（ms）<input id="model-latency-max" type="number" min="0"></label></div><div class="toolbar"><label>成功率 1h 至少（%）<input id="model-success-1h" type="number" min="0" max="100"></label><label>成功率 24h 至少（%）<input id="model-success-24h" type="number" min="0" max="100"></label><label>最少實測次數<input id="model-samples-min" type="number" min="0"></label></div><div class="toolbar"><label>輸入價格上限（USD／1M tokens）<input id="model-input-max" type="number" min="0" step="any"></label><label>輸出價格上限（USD／1M tokens）<input id="model-output-max" type="number" min="0" step="any"></label><label>Cache 價格上限（USD／1M tokens）<input id="model-cache-max" type="number" min="0" step="any"></label></div><label>變更<select id="model-changes"><option value="">全部</option><option value="newly_added">7 天內加入</option><option value="price_changed">價格變更</option><option value="recently_used">7 天內使用</option></select></label><label class="check"><input id="model-usable" type="checkbox">只顯示已啟用且具備認證的連線</label><form id="ranking-form"><details><summary>排序權重</summary><p>強度、速率、額度加權後，再套用實測可靠度；缺資料會標為部分資訊。</p><div class="toolbar"><label>強度<input name="strength" type="number" min="0" max="5" step="0.25" value="1"></label><label>速率<input name="speed" type="number" min="0" max="5" step="0.25" value="1"></label><label>額度<input name="quota" type="number" min="0" max="5" step="0.25" value="1"></label><label>可靠度<input name="reliability" type="number" min="0" max="3" step="0.25" value="1"></label></div><button>保存排序權重</button></details></form>`

const jsModels = `
const notificationRuleNames=["became_free","quota_low","checkin_pending","favorite_recovered","price_changed","outage","recovery"];
async function pollNotifications(deliver=true){const rows=await api("/notifications"),box=$("notification-list");box.replaceChildren();rows.forEach(v=>item(box,v.body,new Date(v.created_at).toLocaleString()+" · "+v.kind));const unread=rows.filter(v=>!v.seen_at);if(deliver&&settings.notifications&&unread.length){if("Notification" in window&&Notification.permission==="granted")unread.slice(0,5).forEach(v=>new Notification("ModelAtlas",{body:v.body,tag:v.id}));await submit("/notifications/seen",{ids:unread.map(v=>v.id)});}}
let modelDisplayLimit=100,catalogDisplayLimit=100;
function normalizedSearch(value){return String(value||"").normalize("NFKD").toLowerCase().replace(/\p{Diacritic}/gu,"").replace(/[\s_./:@-]+/g,"");}
function fuzzyNear(a,b){if(Math.abs(a.length-b.length)>2||a.length>128||b.length>128)return false;let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=1;i<=a.length;i++){const next=[i];for(let j=1;j<=b.length;j++)next[j]=Math.min(next[j-1]+1,row[j]+1,row[j-1]+(a[i-1]===b[j-1]?0:1));row=next;}return row[b.length]<=2;}
function modelMatches(m,q){if(!q)return true;const target=normalizedSearch(q),values=[m.model_id,m.metadata?.model_id,m.metadata?.canonical_id,m.metadata?.display_name,...(m.metadata?.aliases||[]),...(m.offer?.tags||[])].filter(Boolean).map(normalizedSearch);return values.some(v=>v.includes(target)||(target.length>=4&&fuzzyNear(v,target)));}
function knownNumber(value){if(value===null||value===undefined||value==="")return null;const n=Number(value);return Number.isFinite(n)&&n>=0?n:null;}
function meanMetric(value){return knownNumber(value&&typeof value==="object"?value.mean:value);}
function modelMetrics(m){const source=$("model-performance-source").value;if(source==="provider"){const f=m.offer?.provider_performance?.facts||{};return {tps:meanMetric(f.tps),ttft:meanMetric(f.ttft_ms),latency:meanMetric(f.latency_ms),source:"Provider 回報"};}if(source==="external"){const f=m.offer?.external_performance||{};return {tps:f.units==="TPS"?knownNumber(f.average_tokens_per_second):null,ttft:f.units==="MS"?knownNumber(f.average_first_token_latency):null,latency:null,source:"External 參考"};}return {tps:meanMetric(m.performance?.tps),ttft:meanMetric(m.performance?.ttft),latency:meanMetric(m.performance?.latency),source:"我的實測"};}
function modelPrice(m,leg){const price=m.offer?.price?.legs;if(price?.unit!=="USD/1K tokens")return null;const n=knownNumber(price[leg]);return n===null?null:n*1000;}
function modelQuota(m){const rpd=knownNumber(m.offer?.quota?.rpd),tpd=knownNumber(m.offer?.quota?.tpd);return rpd===null||tpd===null?null:Math.min(rpd/(rpd+100),tpd/(tpd+1000000));}
function modelRanking(m){const w={strength:1,speed:1,quota:1,reliability:1,...settings.ranking_weights},metric=modelMetrics(m),strength=knownNumber(m.offer?.strength?.score),values={strength:strength===null?null:Math.min(1,strength/100),speed:metric.tps===null?null:metric.tps/(metric.tps+100),quota:modelQuota(m)};let base=0,used=0,enabled=0;const missing=[];for(const k of ["strength","speed","quota"]){if(w[k]<=0)continue;enabled+=w[k];if(values[k]===null)missing.push(k);else{base+=w[k]*values[k];used+=w[k];}}const reliability=knownNumber(m.performance?.success_rate);if(!m.enabled||used===0)return {score:null,coverage:0,missing:[...missing,"usable"],reliability};return {score:base/used*(reliability===null?1:Math.pow(reliability,w.reliability)),coverage:enabled?used/enabled:0,missing:reliability===null?[...missing,"reliability"]:missing,reliability};}
function numericModelFilter(id,value,max=false,scale=1){const text=$(id).value;if(text==="")return true;const n=knownNumber(value);return n!==null&&(max?n*scale<=Number(text):n*scale>=Number(text));}
function modelPasses(m){const metric=modelMetrics(m),credential=[m.provider_id,m.account_id,m.credential_id].join("/"),selectedKey=$("model-key").value,group=$("model-group").value,meta=m.metadata||{};return m.state===$("model-lifecycle").value&&modelMatches(m,$("model-search").value)&&(!$("model-provider").value||m.provider_id===$("model-provider").value)&&(!selectedKey||credential===selectedKey)&&(!group||m.group===(group==="__DEFAULT__"?"":group))&&(!$("model-capability").value||(m.capabilities||meta.capabilities||[]).includes($("model-capability").value))&&(!$("model-modality").value||(meta.modalities||[]).includes($("model-modality").value))&&(!$("model-category").value||meta.primary_category===$("model-category").value)&&(!$("model-vendor").value||normalizedSearch(meta.vendor).includes(normalizedSearch($("model-vendor").value)))&&(!$("model-price").value||m.price_state===$("model-price").value)&&(!$("model-favorites").value||m[$("model-favorites").value])&&(!$("model-usable").checked||m.enabled)&&numericModelFilter("model-context-min",meta.context_tokens)&&numericModelFilter("model-tps-min",metric.tps)&&numericModelFilter("model-ttft-max",metric.ttft,true)&&numericModelFilter("model-latency-max",metric.latency,true)&&numericModelFilter("model-success-1h",m.reliability?.["1h"]?.success_rate,false,100)&&numericModelFilter("model-success-24h",m.reliability?.["24h"]?.success_rate,false,100)&&numericModelFilter("model-samples-min",m.performance?.samples)&&numericModelFilter("model-input-max",modelPrice(m,"input"),true)&&numericModelFilter("model-output-max",modelPrice(m,"output"),true)&&numericModelFilter("model-cache-max",modelPrice(m,"cache"),true)&&(!$("model-changes").value||($("model-changes").value==="recently_used"?Number(m.performance?.last_request_at)>Date.now()-7*86400000:m.offer?.[$("model-changes").value]));}
function modelSortValue(m,type){const metric=modelMetrics(m);return {strength:knownNumber(m.offer?.strength?.score),tps:metric.tps,ttft:metric.ttft,latency:metric.latency,quota:modelQuota(m),price:modelPrice(m,"input"),recent:knownNumber(m.performance?.last_request_at),new:knownNumber(m.offer?.created_at)}[type];}
function compareModelSort(a,b){const type=$("model-sort").value;if(type==="name")return a.model_id.localeCompare(b.model_id);if(type==="smart"){const x=modelRanking(a),y=modelRanking(b);if(x.score===null||y.score===null)return x.score===y.score?0:x.score===null?1:-1;if(x.coverage!==y.coverage)return y.coverage-x.coverage;return y.score-x.score;}const x=modelSortValue(a,type),y=modelSortValue(b,type);if(x===null||y===null)return x===y?0:x===null?1:-1;return ["ttft","latency","price"].includes(type)?x-y:y-x;}
function modelFilterOptions(){const f=$("ranking-form");if(f.dataset.dirty!=="true")for(const k of ["strength","speed","quota","reliability"])f.elements[k].value=settings.ranking_weights?.[k]??1;for(const [id,values,label] of [["model-key",credentials.filter(c=>c.role==="INFERENCE").map(c=>[[c.provider_id,c.account_id,c.id].join("/"),(providers.find(p=>p.id===c.provider_id)?.name||c.provider_id)+" / "+c.label]),"全部我的 Key"],["model-group",[...new Set(myModels.map(m=>m.group||"__DEFAULT__"))].map(g=>[g,g==="__DEFAULT__"?"預設 Group":g]),"全部 Group"]]){const select=$(id),old=select.value;select.replaceChildren();option(select,"",label);values.forEach(([v,t])=>option(select,v,t));if([...select.options].some(n=>n.value===old))select.value=old;}}

async function olderMessages(id,offset,button){if(id!==$("session").value||busy)return;pauseChatFollow();const height=$("chat").scrollHeight,scroll=$("chat").scrollTop,version=loadVersion;const rows=await api("/messages?session_id="+encodeURIComponent(id)+"&limit=100&offset="+offset);if(version!==loadVersion||id!==$("session").value||busy)return;const fragment=document.createDocumentFragment();rows.forEach(m=>historyMessage(fragment,m));button.replaceWith(fragment);if(rows.length===100){const wrapper=el("div");const more=action(wrapper,"讀取更早訊息",()=>olderMessages(id,offset+100,more));$("chat").prepend(wrapper);}$("chat").scrollTop=scroll+$("chat").scrollHeight-height;chatLastTop=$("chat").scrollTop;chatFollowButton();}
function catalogOffer(m){return {provider_id:m.provider_id,model_id:m.id,metadata:m.metadata||{},capabilities:m.metadata?.capabilities||[],state:"ACTIVE",enabled:false,price_state:"UNKNOWN",offer:{},performance:{}};}
function providerRanking(p){const rows=myModels.filter(m=>m.provider_id===p.id&&m.state==="ACTIVE"&&m.enabled).map(modelRanking).filter(v=>v.score!==null);return rows.length?rows.reduce((n,v)=>n+v.score,0)/rows.length:null;}
async function notesEditor(box,subject,value={}){const form=el("form");box.append(el("h3","備註與標籤"),form);const notes=field(form,"備註","textarea",value.notes||""),tags=field(form,"標籤（逗號分隔）","text",(value.tags||[]).join(","));form.append(el("button","預覽備註變更"));form.addEventListener("submit",async e=>{e.preventDefault();try{assistantAction(await submit("/assistant/actions/preview",{kind:"NOTES",...subject,patch:{notes:notes.value,tags:tags.value.split(",").map(v=>v.trim()).filter(Boolean)}}));}catch(e){notice(e.message,true);}});}

function bindModelControls(){for(const [id,state] of [["bulk-hide","HIDDEN"],["bulk-archive","ARCHIVED"],["bulk-restore","ACTIVE"]])$(id).addEventListener("click",async()=>{try{assistantAction(await submit("/assistant/actions/preview",{kind:"MODEL_BATCH",selections:[...selectedCompare.values()],patch:{state}}));}catch(e){notice(e.message,true);}});["model-scope","model-sort","model-performance-source","model-key","model-group","model-category","model-modality","model-vendor","model-context-min","model-tps-min","model-ttft-max","model-latency-max","model-success-1h","model-success-24h","model-samples-min","model-input-max","model-output-max","model-cache-max","model-changes","model-usable"].forEach(id=>{$(id).addEventListener("input",()=>{modelDisplayLimit=100;renderModels();});});$("ranking-form").addEventListener("input",()=>$("ranking-form").dataset.dirty="true");$("ranking-form").addEventListener("submit",async e=>{e.preventDefault();try{await submit("/settings",{ranking_weights:Object.fromEntries(Object.entries(data(e.target)).map(([k,v])=>[k,Number(v)]))});e.target.dataset.dirty="false";await refresh();notice("排序權重已保存");}catch(e){notice(e.message,true);}});$("provider-sort").addEventListener("change",renderProviders);$("catalog-more").addEventListener("click",()=>{catalogDisplayLimit+=100;renderCatalog();});$("model-more").addEventListener("click",()=>{modelDisplayLimit+=100;renderModels();});}
`
